use super::*;

/// A clause is `{ … }` (named), `* as X` (namespace), a bare identifier (default), or a default
/// combined with either of the first two (`D, { … }` / `D, * as X`).
pub(crate) fn parse_clause(clause: &str, from: &str, type_only: bool) -> Vec<ImportSpec> {
    let clause = clause.trim();
    // default + (named | namespace): a top-level comma before a `{` or `*`.
    if let Some(idx) = clause.find(',') {
        let (left, right) = clause.split_at(idx);
        let left = left.trim();
        let right = right[1..].trim();
        if (right.starts_with('{') || right.starts_with('*')) && !left.is_empty() && !left.starts_with('{') {
            let mut out = vec![ImportSpec {
                from: from.to_string(),
                symbols: vec![left.to_string()],
                type_only,
                kind: "default".to_string(),
            }];
            out.extend(parse_clause(right, from, type_only));
            return out;
        }
    }
    if let Some(inner) = clause.strip_prefix('{').and_then(|c| c.strip_suffix('}')) {
        let symbols: Vec<String> = inner
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        return vec![ImportSpec { from: from.to_string(), symbols, type_only, kind: "named".to_string() }];
    }
    if let Some(name) = clause.strip_prefix('*') {
        // `* as X`
        let binding = name.trim().strip_prefix("as ").map(|s| s.trim()).unwrap_or("").to_string();
        return vec![ImportSpec {
            from: from.to_string(),
            symbols: if binding.is_empty() { Vec::new() } else { vec![binding] },
            type_only,
            kind: "namespace".to_string(),
        }];
    }
    // bare identifier → default import.
    vec![ImportSpec {
        from: from.to_string(),
        symbols: vec![clause.to_string()],
        type_only,
        kind: "default".to_string(),
    }]
}
